#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;
namespace FileCompass {internal static class MediaLayoutTests {internal static int Run(string root){Directory.CreateDirectory(root);var log=new List<string>();MediaConverterWindow w=null;try{w=new MediaConverterWindow(null,new string[0],root,true,delegate{},delegate{}){Left=-18000,Top=-18000};w.Show();NavigationTests.Wait(w.AnalysisTask);for(int i=0;i<80;i++)w.Rows.Add(new MediaRow{Path=Path.Combine(root,new string('n',180)+i+".png"),Image=true,Included=false,Summary=new string('s',300),Status=new string('t',180)});var queue=FluentUiTests.Children<DataGrid>(w).Single();foreach(int h in new[]{820,560,540})foreach(int mode in new[]{0,1})foreach(int tab in new[]{0,1}){w.Width=h<650?800:1180;w.Height=h;w.Mode.SelectedIndex=mode;w.SettingsTabs.SelectedIndex=tab;w.UpdateLayout();NavigationTests.Wait(Task.Delay(150));w.UpdateLayout();string tag=h+"-"+mode+"-"+tab;NextStageTests.Draw(w,Path.Combine(root,tag+".png"));log.Add(tag+" queue="+queue.ActualHeight+" settings="+w.SettingsTabs.ActualHeight+" actual="+w.ActualHeight);if(queue.ActualHeight<64)throw new Exception("Queue clipped "+tag);if(queue.Columns.Sum(x=>x.ActualWidth)>queue.ActualWidth-12)throw new Exception("Queue columns overflow "+tag);if(FluentUiTests.Children<ScrollViewer>(queue).Any(x=>x.ComputedHorizontalScrollBarVisibility==Visibility.Visible))throw new Exception("Horizontal queue scrollbar "+tag);if(FluentUiTests.Children<ScrollViewer>(w.SettingsTabs).Any())throw new Exception("Nested settings scroll "+tag);}log.Add("PASS: 12 layout combinations");return 0;}catch(Exception e){log.Add("FAIL "+e);return 1;}finally{File.WriteAllLines(Path.Combine(root,"result.txt"),log);if(w!=null)w.Close();}}}}
#endif
